"One adult male lead with clear melodic phrasing Add-on slider (see Engine › Sliders) · male": "Una voz principal masculina adulta, de fraseo melódico claro\nDeslizador complementario (ver Motor › Deslizadores) · male",
"Clear hooks, crisp drums and a polished chorus Add-on slider (see Engine › Sliders) · pop": "Ganchos claros, batería nítida y un estribillo pulido\nDeslizador complementario (ver Motor › Deslizadores) · pop",
