"Warm keys, deep pocket and fluid vocal phrasing Add-on slider (see Engine › Sliders) · rnb": "Teclados cálidos, groove profundo y fraseo vocal fluido\nDeslizador complementario (ver Motor › Deslizadores) · rnb",
"Chiming guitars, moving bass and a human drum kit Add-on slider (see Engine › Sliders) · indie-rock": "Guitarras tintineantes, bajo en movimiento y una batería humana\nDeslizador complementario (ver Motor › Deslizadores) · indie-rock",
"Palm-muted power chords and driving chorus drums Add-on slider (see Engine › Sliders) · pop-punk": "Acordes de quinta con palm mute y batería enérgica en el estribillo\nDeslizador complementario (ver Motor › Deslizadores) · pop-punk",
"Heavy guitar riffs, tight kicks and big melodic choruses Add-on slider (see Engine › Sliders) · metal": "Riffs de guitarra pesados, bombos precisos y grandes estribillos melódicos\nDeslizador complementario (ver Motor › Deslizadores) · metal",
"Acoustic strum, twangy fills and an easy backbeat Add-on slider (see Engine › Sliders) · country": "Rasgueo acústico, adornos twang y un backbeat relajado\nDeslizador complementario (ver Motor › Deslizadores) · country",
"Fingerpicked strings and a warm small-room performance Add-on slider (see Engine › Sliders) · acoustic-folk": "Cuerdas punteadas con los dedos y una interpretación cálida de sala pequeña\nDeslizador complementario (ver Motor › Deslizadores) · acoustic-folk",
