"Brings the song to the loudness below: measured first, then set in a second pass. Off: the level stays as it came.": "Lleva la canción a la sonoridad de abajo: primero se mide y luego se ajusta en una segunda pasada. Apagado: el nivel se queda como llegó.",
"Loudness": "Sonoridad",
"The ceiling for the peaks between samples. −1 leaves room for the MP3 and AAC encoders, which add peaks of their own.": "El techo para los picos entre muestras. −1 deja margen a los codificadores MP3 y AAC, que añaden picos propios.",
"Also an MP3 at 320 kbps, beside the WAV and the FLAC.": "También un MP3 a 320 kbps, junto al WAV y el FLAC.",
"also MP3": "también MP3",
"What is upscaled: the take, or any file made from it but an upscaled one.": "Qué se reescala: la toma, o cualquier archivo hecho a partir de ella salvo uno ya reescalado.",
"Mode": "Modo",
"how deep it redraws": "lo profundo que redibuja",
"Subtle — above 12 kHz": "Sutil — por encima de 12 kHz",
"Normal — above 8 kHz": "Normal — por encima de 8 kHz",
"High — above 6 kHz": "Alto — por encima de 6 kHz",
"Extreme — above 4 kHz": "Extremo — por encima de 4 kHz",
"How many versions to draw: they differ only by the noise, and each takes as long as the first. Two let you pick by ear.": "Cuántas versiones dibujar: solo difieren en el ruido y cada una tarda tanto como la primera. Con dos puedes elegir de oído.",
"Variants": "Variantes",
"Keep the original below the cutoff": "Conservar el original por debajo del corte",
"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "Qué pasa por el antizumbido: la toma, o un archivo hecho a partir de ella que no tenga ni antizumbido ni reescalado.",
"Strength": "Intensidad",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "Cuánto del rizado de trama dividir. El oído de Viktor: 100 % adelgazó el comienzo, 80 % fue lo justo.",
"Which file is measured: the take, or any file made from it.": "Qué archivo se mide: la toma, o cualquier archivo hecho a partir de ella.",
"Inspect": "Inspeccionar",
"Where the sound sits: spectrogram, average spectrum, band energy. Lay another take over it to compare.": "Dónde se asienta el sonido: espectrograma, espectro medio, energía por bandas. Superpón otra toma para comparar.",
"Log": "Logarítmica",
"Linear": "Lineal",
"Lays a second spectrum under this one, on the same scale: a file made from this take, or another take.": "Pone un segundo espectro bajo este, en la misma escala: un archivo hecho a partir de esta toma, u otra toma.",
"Compare with": "Comparar con",
"Full screen: zoom and scroll (or double-click the picture). A click plays from there when this take is in the player.": "Pantalla completa: zoom y desplazamiento (o doble clic en la imagen). Un clic reproduce desde ahí cuando esta toma está en el reproductor.",
"Full screen: zoom and scroll": "Pantalla completa: zoom y desplazamiento",
"Whisper listens to this take on Forge and matches what it hears to your lyrics, minute by minute.": "Whisper escucha esta toma en Forge y compara lo que oye con tu letra, minuto a minuto.",
"What Whisper listens to": "Qué escucha Whisper",
"The take as it is, or a stem of it: on the vocal stem Whisper hears the words without the music": "La toma tal cual, o uno de sus stems: en el stem de voz Whisper oye las palabras sin la música",
"Listen with Whisper": "Escuchar con Whisper",
"Karaoke timing": "Sincronía karaoke",
"Time the lines": "Sincronizar las líneas",
"Made from this take": "Creado a partir de esta toma",
"Made from This Take": "Creado a partir de esta toma",
"Search: words, or * and ? as wildcards": "Buscar: palabras, o * y ? como comodines",
"Sort": "Orden",
"newest first": "lo más nuevo primero",
"oldest first": "lo más antiguo primero",
"by title": "por título",
