"Give back": "Devolver",
"The ticked ones, or with none ticked the whole trash: deleted for good, with everything made from them. Asks first.": "Las marcadas o, si no hay ninguna marcada, toda la papelera: se eliminan para siempre, con todo lo creado a partir de ellas. Pregunta antes.",
"Wipe out the trash": "Vaciar la papelera",
