"Dislike the checked": "No me gusta a las marcadas",
"Dislike every checked take (all disliked already: taken back)": "No me gusta a cada toma marcada (si ya lo tenían todas: se retira)",
"Favourite the checked": "Marcar como favoritas",
"Favourite every checked take (all favourites already: taken back)": "Marcar como favorita cada toma marcada (si ya lo eran todas: se retira)",
"Add to workspace": "Añadir al espacio",
"Into that workspace and out of this one (out of every other when you are in All Workspaces)": "A ese espacio y fuera de este (fuera de todos los demás cuando estás en Todos los espacios)",
"Move to workspace": "Mover al espacio",
"Take out of this workspace": "Sacar de este espacio",
"Out of the lists, not deleted: Hidden on the left shows them again": "Fuera de las listas, no eliminadas: «Ocultas» a la izquierda las vuelve a mostrar",
"Hide": "Ocultar",
"Export format": "Formato de exportación",
"FLAC: lossless, about half the size of WAV. WAV: for tools that take nothing else.": "FLAC: sin pérdidas, cerca de la mitad del tamaño del WAV. WAV: para herramientas que no aceptan otra cosa.",
"Also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "También cada archivo creado a partir de cada toma (remasterizaciones, stems, reescalados, archivos con antizumbido), con el nombre de la toma.",
"with what is made from them": "con lo creado a partir de ellas",
