"Export ZIP": "Exportar ZIP",
"To the trash": "A la papelera",
"The Librarian lives in Forge's lab, which does not answer: not found": "El Bibliotecario vive en el laboratorio de Forge, que no responde: no encontrado",
"a LoRA for YuE2 from your own songs · the guide: LORA-TRAINING.md": "una LoRA para YuE2 a partir de tus propias canciones · la guía: LORA-TRAINING.md",
