"Drag to resize · double-click for the default width": "Arrastra para cambiar el tamaño · doble clic para el ancho por defecto",
"Compose column width": "Ancho de la columna de composición",
"Takes list width": "Ancho de la lista de tomas",
"Pick a take on the right": "Elige una toma a la derecha",
