"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "Tal como la hizo el estudio (y la terminó el Pulidor), sin DAW de por medio. La toma en mano:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Abre una toma, reproduce una o marca una en el Bibliotecario: su WAV, FLAC y MP3 aparecen aquí.",
