"It takes a GPU of its own for hours; a set without its latent cache gets one first (a second or two a track).": "Ocupa una GPU propia durante horas; un conjunto sin su caché latente la obtiene primero (un segundo o dos por pista).",
"It takes a GPU of its own for hours; the first run also fetches Comfy-Org’s YuE2 weights.": "Ocupa una GPU propia durante horas; la primera ejecución también descarga los pesos de YuE2 de Comfy-Org.",
"Training may take GPU{0}, the studio’s own card: if it does, synthesis waits until the run ends (Engine → GPUs gives training another card).": "El entrenamiento puede ocupar GPU{0}, la tarjeta propia del estudio: si lo hace, la síntesis espera hasta que termine la ejecución (Motor → GPU da al entrenamiento otra tarjeta).",
"Start training": "Empezar el entrenamiento",
"Training {0}": "Entrenando {0}",
"Listener": "Oyente",
"drafts each track’s style from what it hears; a draft, read and correct it": "esboza el estilo de cada pista a partir de lo que oye; un borrador, léelo y corrígelo",
"Trigger": "Activador",
"Shared line": "Línea común",
"after the track’s tags": "tras las etiquetas de la pista",
"the album’s vibe": "el ambiente del álbum",
"Write into the captions": "Escribir en las descripciones",
"Listening… {0} / {1}": "Escuchando… {0} / {1}",
"Listen to {0}": "Escuchar {0}",
"Listen to {0}?": "¿Escuchar {0}?",
"Omni hears 120 s of every track and drafts its style. Drafts heard before are kept aside (styles.DATE.json); the captions change only when you write them.": "Omni oye 120 s de cada pista y esboza su estilo. Los borradores oídos antes se apartan (styles.DATE.json); las descripciones solo cambian cuando las escribes.",
"Listen": "Escuchar",
"Listening to {0}": "Escuchando {0}",
"Write {#0} styles into the captions of {1}?": "¿Escribir {0} estilos en las descripciones de {1}?",
"Each first line becomes: {0} The lyrics stay.": "Cada primera línea pasa a ser: {0} La letra se queda.",
"Write": "Escribir",
"{#0} captions written": {"one": "{0} descripción escrita", "many": "{0} descripciones escritas", "other": "{0} descripciones escritas"},
"drafts here by {0}": "borradores aquí de {0}",
"The studio’s trainer is missing {0}:": "Al entrenador del estudio le falta {0}:",
"Comfy-Org's YuE2 {0} weights": "los pesos {0} de YuE2 de Comfy-Org",
"the realaudio tokenizer head": "la cabeza del tokenizador realaudio",
"and": "y",
"AI-Toolkit is not found at": "AI-Toolkit no se encuentra en",
": clone ostris/ai-toolkit there (or set AITK_ROOT for the lab), or train with the studio’s own trainer.": ": clona allí ostris/ai-toolkit (o define AITK_ROOT para el laboratorio), o entrena con el entrenador propio del estudio.",
"The realaudio tokenizer is missing from": "Falta el tokenizador realaudio en",
"{#0} characters, about {#1} tokens.": "{0} caracteres, unos {1} tokens.",
"Style and lyrics together: about {#0} of {#1} tokens.": "Estilo y letra juntos: unos {0} de {1} tokens.",
"Style and lyrics together: about {#0} of {#1} tokens — too long for a full-length song and score.": "Estilo y letra juntos: unos {0} de {1} tokens — demasiado largo para una canción completa con partitura.",
"Unlike the model's training styles:": "No se parece a los estilos con los que se entrenó el modelo:",
"longer than 1,600 characters (the official examples stop at 999)": "más de 1600 caracteres (los ejemplos oficiales llegan hasta 999)",
"{#0} Unicode arrow (→): write -> instead": "flechas Unicode (→): {0}: escribe -> en su lugar",
"{#0} Unicode arrows (→): write -> instead": "flechas Unicode (→): {0}: escribe -> en su lugar",
"dynamics marks (never in the official styles)": "marcas de dinámica (nunca en los estilos oficiales)",
"{#0} \"Label:\" fields (5 of 110 official styles use any)": "{0} campos «Label:» (5 de los 110 estilos oficiales usan alguno)",
"{#0} bracket line in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "líneas entre paréntesis en la letra con «Label:», una flecha o una marca p/f: {0} (ninguna en los ejemplos oficiales)",
"{#0} bracket lines in the lyrics with a \"Label:\", an arrow or a p/f mark (none in the official examples)": "líneas entre paréntesis en la letra con «Label:», una flecha o una marca p/f: {0} (ninguna en los ejemplos oficiales)",
"{#0} instruments": {"one": "{0} instrumento", "many": "{0} instrumentos", "other": "{0} instrumentos"},
"{#0} heard": "oídos: {0}",
"{#0} questioned": "en duda: {0}",
"{#0} not identified": "sin identificar: {0}",
"{#0} not judged yet": "aún sin valorar: {0}",
"the Librarian does not answer: no probes to play": "el Bibliotecario no responde: no hay pruebas que reproducir",
"{#0} styles": {"one": "{0} estilo", "many": "{0} estilos", "other": "{0} estilos"},
"{#0} style": {"one": "{0} estilo", "many": "{0} estilos", "other": "{0} estilos"},
"what a probe gave instead of its instrument": "lo que dio una prueba en lugar de su instrumento",
"Nothing matches.": "Nada coincide.",
"⚠ A name in the style is a request, not a promise. What ▶ A and ▶ B play is what YuE2 gives for it, about nine times in ten.": "⚠ Un nombre en el estilo es una petición, no una promesa. Lo que suenan ▶ A y ▶ B es lo que YuE2 da para él, más o menos nueve veces de cada diez.",
"Some probes are superb, and A and B agree, yet the instrument is not the one asked for: trust the ear, not the name.": "Algunas pruebas son magníficas, y A y B coinciden, pero el instrumento no es el pedido: fíate del oído, no del nombre.",
"What YuE2 was asked to play, one instrument or one style at a time, in probes of two minutes (one minute for the first ones), two seeds each, A and B.": "Lo que se pidió tocar a YuE2, un instrumento o un estilo cada vez, en pruebas de dos minutos (un minuto las primeras), dos semillas cada una, A y B.",
"An instrument shapes the style of the whole piece: naming one moves the arrangement too. A crackle or a rustle of paper, as on a worn record, is an unlucky seed: make it again on another.": "Un instrumento da forma al estilo de toda la pieza: nombrarlo también mueve el arreglo. Un crepitar o un roce de papel, como en un disco gastado, es una semilla desafortunada: créala de nuevo con otra.",
