"A run is in progress; the next song is queued behind it.": "Hay una ejecución en marcha; la próxima canción está en cola detrás.",
"Your note on this take, kept with it: saved as you type, and the same note in the Librarian.": "Tu nota sobre esta toma, guardada con ella: se guarda mientras escribes, y es la misma nota que en el Bibliotecario.",
