"Unload model frees it now; the next song loads it again.": "«Liberar el modelo» lo libera ahora; la próxima canción lo vuelve a cargar.",
"This server does not report its hardware.": "Este servidor no informa de su hardware.",
"Taken out of “{0}”": "Sacada de «{0}»",
"Added to “{0}”": "Añadida a «{0}»",
"fetching…": "obteniendo…",
"fetching {0} of {1} MB · {2} MB/s": "obteniendo {0} de {1} MB · {2} MB/s",
