"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "Restaurar trae de vuelta la copia publicada en Hugging Face: las tomas que le faltan vuelven, los títulos y las notas regresan a los publicados, y lo que se le añadió sale del espacio (esas tomas se quedan en la biblioteca; sus propias secciones se quedan).\n\nPara conservar el tuyo tal como está: «Cancelar», renombra tu espacio (⋯ junto a su nombre, luego «Renombrar…») y «Traer» de nuevo: el original llega a su lado con su propio nombre.",
