"Its takes stay as they are: they are heard and read, never changed, moved or thrown away, and they leave All Workspaces and the search (a take also in a workspace that is not frozen stays there). The workspace greys out; Unfreeze in its ⋯ menu brings everything back.": "Sus tomas se quedan como están: se escuchan y se leen, pero no se cambian, no se mueven ni se tiran, y salen de «Todos los espacios» y de la búsqueda (una toma que también está en un espacio no congelado sigue allí). El espacio se vuelve gris; «Descongelar» en su menú ⋯ lo devuelve todo.",
