"Drag: the form takes 55 to 70 % of the width; below 55 the takes take 60 % and the form one column · double-click: the default": "Arrastra: el formulario ocupa del 55 al 70 % del ancho; por debajo de 55 las tomas ocupan el 60 % y el formulario una columna · doble clic: el valor por defecto",
