"Out of the list; its checkpoint stays in the Trainer's run {0} (the Trainer puts it back)": "Fuera de la lista; su checkpoint se queda en la ejecución {0} del Entrenador (el Entrenador lo devuelve)",
"muted": "silenciado",
"Right-click: back in the run": "Clic derecho: de vuelta en la ejecución",
"Its trigger word goes at the style’s end by itself when the song is made": "Su palabra clave va sola al final del estilo cuando se hace la canción",
"{0}: its trigger word “{1}” goes at the style's end when the song is made.": "{0}: su palabra clave «{1}» va al final del estilo cuando se hace la canción.",
"Style as tags": "Estilo en etiquetas",
"the most important first": "lo más importante primero",
