"drop a picture here, paste one (Ctrl+V), or take the stage's with «As reference»": "suelta una imagen aquí, pega una (Ctrl+V) o toma la del escenario con «Como referencia»",
"As reference": "Como referencia",
"The take's cover": "La portada de la toma",
"The cover of the take picked on the right as the reference: with «Paint around it» it becomes a 16:9 for the video or a 9:16 for a short": "La portada de la toma elegida a la derecha como referencia: con «Pintar alrededor» se vuelve un 16:9 para el vídeo o un 9:16 para un short",
