"Mask…": "Máscara…",
"Mask ✓": "Máscara ✓",
"Paint what of the picture to repaint (white repaints, the rest stays as it is): as inpainting": "Pinta qué de la imagen repintar (lo blanco se repinta, el resto queda como está): como inpainting",
"No reference picture": "Sin imagen de referencia",
"No reference: paint from the noise": "Sin referencia: pintar desde el ruido",
"the edges painted anew": "los bordes se pintan de nuevo",
"Grow": "Crecer",
"Edge": "Borde",
"Grain": "Grano",
"The mask grown by so many pixels (negative: shrunk), as ComfyUI's GrowMask: room for the new paint to meet the old": "La máscara crecida tantos píxeles (negativo: encogida), como el GrowMask de ComfyUI: sitio para que la pintura nueva se encuentre con la vieja",
"How soft the mask's edge is, in pixels: the new paint fades into the old over it": "Qué tan suave es el borde de la máscara, en píxeles: sobre él la pintura nueva se funde con la vieja",
"Soft repainting (differential diffusion, A1111's soft inpainting): where the edge is grey the picture changes only in the last steps, a little; no seam": "Repintado suave (differential diffusion, el soft inpainting de A1111): donde el borde es gris la imagen cambia solo en los últimos pasos, un poco; sin costura",
"How much of the painting the kept part takes, at each step and at the end: its grain and light sewn to the new paint (0 keeps it exactly)": "Cuánto de la pintura toma la parte que se conserva, en cada paso y al final: su grano y su luz cosidos a la pintura nueva (0 la deja exacta)",
"The prompt the take's artwork was drawn from, or one from its title and style, to start from": "El prompt con el que se pintó la portada de la toma, o uno de su título y su estilo, para empezar",
"1:1 · 1280² · for the cover": "1:1 · 1280² · para la portada",
"16:9 · 1920×1080 · for a video": "16:9 · 1920×1080 · para un vídeo",
"9:16 · 1080×1920 · for a short": "9:16 · 1080×1920 · para un short",
"Shapes": "Formas",
"empty: a new one": "vacía: una nueva",
"The seed decides the picture: empty for a new one each time; the seed of a picture you liked draws it again (each run shows its seed)": "La semilla decide la imagen: vacía para una nueva cada vez; la semilla de una imagen que te gustó la vuelve a pintar (cada ejecución muestra su semilla)",
"new": "nueva",
"A new seed each time": "Una semilla nueva cada vez",
"Each variation is the next seed (the seed, the seed + 1, …), in every shape picked": "Cada variación es la semilla siguiente (la semilla, la semilla + 1, …), en cada forma elegida",
"The seed's mode": "El modo de la semilla",
"Random (−1)": "Aleatoria (−1)",
"Random, fixed": "Aleatoria, fija",
"Fixed": "Fija",
"A new seed each run: the field stays empty (−1)": "Una semilla nueva en cada ejecución: el campo queda vacío (−1)",
"A random seed put in now, then kept for every run (choose it again for another)": "Una semilla al azar puesta ahora y guardada para cada ejecución (elígela otra vez para otra)",
"The seed as written, every run": "La semilla tal como está escrita, en cada ejecución",
"After each run the seed moves on past the seeds it used": "Tras cada ejecución la semilla pasa más allá de las que usó",
"After each run the seed moves back by the seeds it used": "Tras cada ejecución la semilla retrocede tantas como usó",
"Fine-tune": "Fine-tune",
"Sampler": "Sampler",
"Schedule": "Programación",
"Guidance": "Guía",
"How many steps from the noise to the picture: Krea 2 and Qwen-Image 2512 with Lightning 4 to 16 (8 their own), 2512 without it and Qwen-Image 2.1 10 to 60": "Cuántos pasos del ruido a la imagen: Krea 2 y Qwen-Image 2512 con Lightning de 4 a 16 (8 los suyos), 2512 sin él y Qwen-Image 2.1 de 10 a 60",
"How each step is taken. Euler: the plain step; Euler SDE: fresh noise each step (soft on Qwen without Lightning). ER-SDE: a stochastic solver of third order, one look a step. RES 2s and 3s: the refined exponential solver, two or three looks a step (ODE: without noise). Heun++: up to three looks a step. Exp Heun 2 x0: the exponential Heun, two looks (SDE: with noise). More looks: finer, and as many times longer": "Cómo se da cada paso. Euler: el paso sencillo; Euler SDE: ruido fresco en cada paso (suave en Qwen sin Lightning). ER-SDE: un resolvedor estocástico de tercer orden, una mirada por paso. RES 2s y 3s: el resolvedor exponencial refinado, dos o tres miradas por paso (ODE: sin ruido). Heun++: hasta tres miradas por paso. Exp Heun 2 x0: el Heun exponencial, dos miradas (SDE: con ruido). Más miradas: más fino, y tantas veces más largo",
"How the steps are spread from the noise to the picture: Simple (the painter's own), Karras and Exponential (more steps near the end, for detail; with Lightning they can paint the subject twice), Beta and Beta 57 (more at both ends), KL optimal (Align Your Steps' spacing), SGM uniform (even in time), Bong tangent (two slopes, through the middle)": "Cómo se reparten los pasos del ruido a la imagen: Simple (la del pintor), Karras y Exponential (más pasos hacia el final, para el detalle; con Lightning pueden pintar el motivo dos veces), Beta y Beta 57 (más en los dos extremos), KL optimal (el espaciado de Align Your Steps), SGM uniform (igual en el tiempo), Bong tangent (dos pendientes, por el centro)",
"Lightning's strength: 1.0 as its makers give it, lower for a fine-tune (0.55 with 12 steps)": "La fuerza de Lightning: 1.0 como la dan sus autores, más baja para un fine-tune (0.55 con 12 pasos)",
"Without Lightning: how closely the picture follows the prompt (true CFG, two passes a step); 4 is Qwen-Image's own": "Sin Lightning: cuán de cerca sigue la imagen al prompt (true CFG, dos pasadas por paso); 4 es el propio de Qwen-Image",
"The painter's own steps, sampler and schedule": "Los pasos, el sampler y la programación propios del pintor",
"Live preview": "Vista previa en vivo",
"Each step of the painting over its place, from the noise to the picture: an eighth of its size, seen without the decoder, so it costs nothing. Off: the place waits for the picture": "Cada paso de la pintura sobre su sitio, del ruido a la imagen: a un octavo de su tamaño, sin el decodificador, así que no cuesta nada. Apagado: el sitio espera la imagen",
"Add…": "Añadir…",
"The adapters for this painter in artwork/loras/ (its family's folder, any folders below it): pick up to four": "Los adaptadores de este pintor en artwork/loras/ (la carpeta de su familia y las de dentro): elige hasta cuatro",
"Together": "Juntos",
"All together": "Todos juntos",
"All the adapters' strengths together: stacked, they add up, and past about {#0} the picture burns (its colours and edges overdone), however modest each one is. Green to {#1}, amber to {#2}, red past it. Drag it to move them all at once, each in proportion.": "Las fuerzas de todos los adaptadores juntas: apilados, se suman, y pasado cerca de {#0} la imagen se quema (colores y bordes pasados de rosca), por modesto que sea cada uno. Verde hasta {#1}, ámbar hasta {#2}, rojo más allá. Arrástralo para mover todos a la vez, cada uno en proporción.",
