"It takes: the boxes' undo history, a lifted frame, the music playing, a writer's answer still on its way, an upload under way.\n\nIt keeps: the song in the form (its words and its knobs), a run under way (it comes back with its clock), the library, the Writer's notebook.\n\nCtrl+F5 reloads at once.": "Se lleva: el historial de deshacer de los campos, un marco levantado, la música que suena, una respuesta del escritor aún en camino, una subida en curso.\n\nConserva: la canción del formulario (sus palabras y sus mandos), una ejecución en curso (vuelve con su reloj), la biblioteca, el cuaderno del Escritor.\n\nCtrl+F5 recarga al instante.",
"It takes: the boxes' undo history, a lifted frame, the music playing, a writer's answer still on its way, an upload under way.\n\nIt keeps: the song in the form (its words and its knobs), a run under way (it comes back with its clock), the library, the Writer's notebook.\n\nSave to the Writer keeps this song there as well before the reload: a new version of the document in hand, or a document of its own.\n\nCtrl+F5 reloads at once.": "Se lleva: el historial de deshacer de los campos, un marco levantado, la música que suena, una respuesta del escritor aún en camino, una subida en curso.\n\nConserva: la canción del formulario (sus palabras y sus mandos), una ejecución en curso (vuelve con su reloj), la biblioteca, el cuaderno del Escritor.\n\n«Guardar en el Escritor» guarda también allí esta canción antes de recargar: una versión nueva del documento en mano, o un documento propio.\n\nCtrl+F5 recarga al instante.",
"Reset the output to the defaults?": "¿Restablecer la salida a los valores por defecto?",
