"Not in OpenRouter's list: check the name": "No está en la lista de OpenRouter: revisa el nombre",
"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "Cualquier modelo de openrouter.ai/models, escrito proveedor/modelo; el campo ofrece la lista entera mientras escribes, cada uno con su precio por millón de tokens de entrada y salida. Las elecciones rápidas lo rellenan.",
"Strong and the cheapest per word: the default · {0}": "Fuerte y la más barata por palabra: la predeterminada · {0}",
