"Export all": "Exportar todo",
"Export all: every document of the Writer, with its versions, the takes made from it and its trash, in one file (a backup)": "Exportar todo: cada documento del Escritor, con sus versiones, las tomas hechas con él y su papelera, en un archivo (una copia de seguridad)",
