"The documents column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "La columna de los documentos: arrastra para ensanchar; ← → desde el teclado; Home o doble clic para su ancho de origen",
"Writer backup: {0} documents and {1} in the trash, into {2}": "Copia del Escritor: {0} documentos y {1} en la papelera, en {2}",
