"Indie and alternative, sung in English to the words of «Scarborough Fair» (a traditional English ballad).": "Indie y alternativo, cantada en inglés con la letra de «Scarborough Fair» (una balada tradicional inglesa).",
"Country and Americana, sung in English to the words of «Scarborough Fair» (a traditional English ballad).": "Country y americana, cantada en inglés con la letra de «Scarborough Fair» (una balada tradicional inglesa).",
