"Photos, also JPEG-compressed or a little blurred: detailed and natural. The studio's default; slow.": "Fotos, también comprimidas en JPEG o algo borrosas: detallado y natural. El predeterminado del estudio; lento.",
"Clean photos (not compressed, not blurred): the most faithful detail on good input. Slow.": "Fotos limpias (sin compresión ni desenfoque): el detalle más fiel con una buena entrada. Lento.",
"Photos taken from the web: JPEG or WebP compression, blur and noise mended as it upscales. Slow.": "Fotos sacadas de la web: la compresión JPEG o WebP, el desenfoque y el ruido se arreglan al escalar. Lento.",
"Photos with JPEG compression; keeps the grain and the noise. The slowest here, and in full precision only.": "Fotos con compresión JPEG; conserva el grano y el ruido. El más lento aquí, y solo en precisión completa.",
"Degraded photos, faces too: a large model trained on blur, noise and compression. Slow, and the heaviest on the card.": "Fotos degradadas, también caras: un modelo grande entrenado con desenfoque, ruido y compresión. Lento, y el más pesado para la tarjeta.",
"Photos with JPEG compression and blur: a large model for realistic detail. Slow and heavy.": "Fotos con compresión JPEG y desenfoque: un modelo grande para un detalle realista. Lento y pesado.",
"Photos, quick: mends little, keeps the most of the picture's own texture.": "Fotos, rápido: arregla poco, conserva lo más de la textura propia de la imagen.",
"Photos, quick: mends blur, noise and compression in the middle measure.": "Fotos, rápido: arregla desenfoque, ruido y compresión en una medida media.",
"Photos, quick: mends strongly (smoother). The first pass of Viktor's ComfyUI chain.": "Fotos, rápido: arregla con fuerza (más suave). La primera pasada de la cadena ComfyUI de Viktor.",
"Realistic pictures, best on faces, hair and nature; a soft, natural look with few artifacts, for fairly clean input (not grainy). Quick. Non-commercial.": "Imágenes realistas, mejor en caras, pelo y naturaleza; un aspecto suave y natural con pocos artefactos, para una entrada bastante limpia (sin grano). Rápido. No comercial.",
"ClearReality's softer sister: kinder to rendered and game pictures, weaker on real photos. Quick. Non-commercial.": "La hermana más suave de ClearReality: más amable con renders e imágenes de juegos, más floja con fotos reales. Rápido. No comercial.",
"Realistic photos with noise and compression. Quick.": "Fotos realistas con ruido y compresión. Rápido.",
"An all-rounder for clean or lightly compressed pictures (JPEG quality 75 and up). Quick.": "Un todoterreno para imágenes limpias o algo comprimidas (calidad JPEG de 75 en adelante). Rápido.",
"NMKD Siax again, as safetensors: the same model as 4x_NMKD-Siax_200k. Quick.": "NMKD Siax otra vez, en safetensors: el mismo modelo que 4x_NMKD-Siax_200k. Rápido.",
"General pictures with more detail and less smoothing: skin and fine texture do not turn mushy. Quick. Non-commercial. The third pass of Viktor's chain.": "Imágenes generales con más detalle y menos suavizado: la piel y la textura fina no se vuelven papilla. Rápido. No comercial. La tercera pasada de la cadena de Viktor.",
"Remacri, smoother: fewer edges and less grain. Quick. Non-commercial.": "Remacri, más suave: menos bordes y menos grano. Rápido. No comercial.",
"Natural pictures with sharpness and detail in balance. Quick. Non-commercial. The last pass of Viktor's chain.": "Imágenes naturales con nitidez y detalle en equilibrio. Rápido. No comercial. La última pasada de la cadena de Viktor.",
"UltraMix leaning to repair: damaged and compressed input. Quick. Non-commercial.": "UltraMix inclinado a reparar: entrada dañada y comprimida. Rápido. No comercial.",
"UltraMix, smoother: soft surfaces, little sharpening. Quick. Non-commercial.": "UltraMix, más suave: superficies suaves, poco enfoque. Rápido. No comercial.",
"Almost anything: photos, anime, cartoons, illustration, artwork and text; sharp. Slow. Non-commercial.": "Casi cualquier cosa: fotos, anime, dibujos animados, ilustración, arte y texto; nítido. Lento. No comercial.",
"UltraSharp V2 again: the same file as 4x_UltraSharp_v2. Slow. Non-commercial.": "UltraSharp V2 otra vez: el mismo archivo que 4x_UltraSharp_v2. Lento. No comercial.",
"Realistic pictures, neither soft nor sharp. Quick.": "Imágenes realistas, ni suaves ni nítidas. Rápido.",
"Realistic pictures, sharper. Quick.": "Imágenes realistas, más nítidas. Rápido.",
"Realistic pictures, the sharpest of the three. Quick.": "Imágenes realistas, el más nítido de los tres. Rápido.",
